"use client";
/* Rocket, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Rocket(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("rocket"); }, []);
  return React.createElement("piix-pal", { "pal": "rocket", ...piixAttrs(props) });
}

export default Rocket;
